class s{static Fixed(e,t=2){let i="";for(let r=0;r<t;r++)i+="0";let c=parseInt("1"+i);return Math.floor(e*c)/c}static FileSize(e){return e/1024<1024?(e/1024).toFixed(2)+"KB":e/1024/1024<1024?(e/1024/1024).toFixed(2)+"MB":e/1024/1024/1024<1024?(e/1024/1024/1024).toFixed(2)+"GB":(e/1024/1024/1024/1024).toFixed(2)+"TB"}static priceEncode(e,t=2){return parseFloat(e).toFixed(t).toString().replace(/\d{1,3}(?=(\d{3})+(\.\d*)?$)/g,"$&,")}static priceDecode(e,t=2){return parseFloat(e.replace(/,/g,"")).toFixed(t)}static PriceQoq(e=0,t=0,i=2){return e-t==0?"0":e==0?"-100":t==0?"100":parseFloat(String((e-t)/t*100)).toFixed(i).toString().replace(/\d{1,3}(?=(\d{3})+(\.\d*)?$)/g,"$&,")}static telEncode(e,t=" "){if(!/^[1]\d{10}$/.test(e))return e;let c="";for(let r=0;r<e.length;r++)(r==3||r==7)&&(c+=t),c+=e.substring(r,r+1);return c}static telDecode(e,t=" "){const i=new RegExp("/"+t+"/g");return e.replace(i,"")}static cardEncode(e,t=" "){if(!/^\d+$/.test(e))return e;let c="";for(let r=0;r<e.length;r++)r%4===0&&(c+=t),c+=e.substring(r,r+1);return c}static cardDecode(e,t=" "){const i=new RegExp("/"+t+"/g");return e.replace(i,"")}}export{s as F};
